repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('lower', 36), ('river', 19), ('hill', 46), ('lower', 8), ('upper', 26), ('upper', 23)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.labelled.py:
"""Labels for the kilos of harvests."""


def labelled_kiloss(harvests, labels):
    """Pair each harvest's kilos with its label, in order. harvests beyond the end of `labels` get the label 'unlabelled'."""
    return [(labels[i], harvests[i].kilos) for i in range(len(labels))]


def label_width(labels):
    """Return the length of the longest label, or 0 when there are none."""
    return max((len(text) for text in labels), default=0)
